328	    birth: Mutex<HashSet<String>>,
329	    /// Key: (task_id, node_id) → (output, ok, ts, seq)
330	    checkpoints: Mutex<HashMap<(String, String), CheckpointValue>>,
331	    /// Per-task monotonic seq counter. Key: task_id.
332	    seq_counters: Mutex<HashMap<String, i64>>,
333	    /// Per-task terminal seq. Key: task_id.
334	    terminal_seqs: Mutex<HashMap<String, i64>>,
335	    /// In-progress node starts. Key: (task_id, node_id) → (seq, ts).
336	    starts: Mutex<HashMap<(String, String), (i64, i64)>>,
