+                tool_call_id,
+                title: fold.title.unwrap_or_default(),
+                kind: fold.kind.unwrap_or_default(),
+                status: fold.status.unwrap_or_default(),
+                locations: fold.locations.unwrap_or_default(),
+                content: fold.content,
