    assert_eq!(
        frames,
        vec![
            (3, "tool_call".to_string()),
            (4, "node_finished".to_string()),
            (4, "snapshot_complete".to_string()),
            (5, "terminal".to_string()),
        ],
        "terminal-task reattach must surface the folded rich tool_call frame: {frames:?}"
    );
}

